CREATE TABLE public.care_blocks (blocker_id uuid NOT NULL REFERENCES public.profiles(id), blocked_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
GRANT SELECT,INSERT,DELETE ON public.care_blocks TO authenticated; GRANT ALL ON public.care_blocks TO service_role; ALTER TABLE public.care_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own blocks read" ON public.care_blocks FOR SELECT TO authenticated USING(blocker_id=auth.uid()); CREATE POLICY "Own block create" ON public.care_blocks FOR INSERT TO authenticated WITH CHECK(blocker_id=auth.uid() AND EXISTS(SELECT 1 FROM public.care_appointments a WHERE public.care_can_access(a.id) AND ((a.farmer_id=auth.uid() AND a.vet_id=blocked_id) OR (a.vet_id=auth.uid() AND a.farmer_id=blocked_id)))); CREATE POLICY "Own block remove" ON public.care_blocks FOR DELETE TO authenticated USING(blocker_id=auth.uid());
CREATE OR REPLACE FUNCTION public.care_not_blocked(_a uuid,_b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.care_blocks WHERE (blocker_id=_a AND blocked_id=_b) OR (blocker_id=_b AND blocked_id=_a)); $$; REVOKE ALL ON FUNCTION public.care_not_blocked(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_not_blocked(uuid,uuid) TO authenticated;
CREATE TABLE public.care_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid NOT NULL REFERENCES public.care_appointments(id), sender_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT ON public.care_messages TO authenticated; GRANT ALL ON public.care_messages TO service_role; ALTER TABLE public.care_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY "Authorized conversation read" ON public.care_messages FOR SELECT TO authenticated USING(public.care_can_access(appointment_id));
CREATE OR REPLACE FUNCTION public.care_send_message(_appointment uuid,_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.care_appointments; mid uuid; BEGIN SELECT * INTO a FROM public.care_appointments WHERE id=_appointment; IF NOT public.care_can_access(_appointment) OR NOT public.care_not_blocked(a.farmer_id,a.vet_id) OR a.status NOT IN('requested','confirmed','completed') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; INSERT INTO public.care_messages(appointment_id,sender_id,body) VALUES(_appointment,auth.uid(),btrim(_body)) RETURNING id INTO mid; INSERT INTO public.care_notifications(recipient_id,appointment_id,kind,dedupe_key) VALUES(CASE WHEN auth.uid()=a.farmer_id THEN a.vet_id ELSE a.farmer_id END,a.id,'message',mid::text); RETURN mid; END $$; REVOKE ALL ON FUNCTION public.care_send_message(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_send_message(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_read_messages(_appointment uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.care_can_access(_appointment) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; UPDATE public.care_messages SET read_at=now() WHERE appointment_id=_appointment AND sender_id<>auth.uid() AND read_at IS NULL; END $$; REVOKE ALL ON FUNCTION public.care_read_messages(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_read_messages(uuid) TO authenticated;
CREATE TABLE public.care_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES public.profiles(id), reported_id uuid NOT NULL REFERENCES public.profiles(id), appointment_id uuid NOT NULL REFERENCES public.care_appointments(id), reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 1000), status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','reviewed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.care_reports TO authenticated; GRANT ALL ON public.care_reports TO service_role; ALTER TABLE public.care_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own reports" ON public.care_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid()); CREATE POLICY "Participant reports" ON public.care_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='submitted' AND public.care_can_access(appointment_id) AND EXISTS(SELECT 1 FROM public.care_appointments a WHERE a.id=appointment_id AND ((a.farmer_id=auth.uid() AND a.vet_id=reported_id) OR (a.vet_id=auth.uid() AND a.farmer_id=reported_id))));
CREATE TABLE public.care_consultations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid NOT NULL REFERENCES public.care_appointments(id), author_id uuid NOT NULL REFERENCES public.profiles(id), farmer_report text NOT NULL CHECK(length(farmer_report)<=2000), assessment text NOT NULL CHECK(length(btrim(assessment)) BETWEEN 1 AND 4000), recommendations text NOT NULL CHECK(length(recommendations)<=4000), follow_up_date date, supersedes_id uuid UNIQUE REFERENCES public.care_consultations(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.care_consultations TO authenticated; GRANT ALL ON public.care_consultations TO service_role; ALTER TABLE public.care_consultations ENABLE ROW LEVEL SECURITY; CREATE POLICY "Authorized consultation read" ON public.care_consultations FOR SELECT TO authenticated USING(public.care_can_access(appointment_id));
CREATE TABLE public.care_prescriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid NOT NULL REFERENCES public.care_appointments(id), consultation_id uuid NOT NULL REFERENCES public.care_consultations(id), author_id uuid NOT NULL REFERENCES public.profiles(id), vet_name text NOT NULL, qualifications text NOT NULL, licence text NOT NULL, medicine text NOT NULL CHECK(length(btrim(medicine)) BETWEEN 1 AND 200), dose text NOT NULL CHECK(length(btrim(dose)) BETWEEN 1 AND 200), route text NOT NULL CHECK(length(btrim(route)) BETWEEN 1 AND 100), frequency text NOT NULL CHECK(length(btrim(frequency)) BETWEEN 1 AND 200), duration text NOT NULL CHECK(length(btrim(duration)) BETWEEN 1 AND 200), instructions text NOT NULL CHECK(length(instructions)<=2000), withdrawal_guidance text NOT NULL CHECK(length(withdrawal_guidance)<=1000), supersedes_id uuid UNIQUE REFERENCES public.care_prescriptions(id), issued_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.care_prescriptions TO authenticated; GRANT ALL ON public.care_prescriptions TO service_role; ALTER TABLE public.care_prescriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Authorized prescription read" ON public.care_prescriptions FOR SELECT TO authenticated USING(public.care_can_access(appointment_id));
CREATE TABLE public.care_administrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prescription_id uuid NOT NULL REFERENCES public.care_prescriptions(id), farmer_id uuid NOT NULL REFERENCES public.profiles(id), administration_date date NOT NULL, administered_by text NOT NULL CHECK(length(btrim(administered_by)) BETWEEN 1 AND 100), notes text NOT NULL CHECK(length(notes)<=1000), created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.care_administrations TO authenticated; GRANT ALL ON public.care_administrations TO service_role; ALTER TABLE public.care_administrations ENABLE ROW LEVEL SECURITY; CREATE POLICY "Authorized administration history" ON public.care_administrations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.care_prescriptions p WHERE p.id=prescription_id AND public.care_can_access(p.appointment_id)));
CREATE OR REPLACE FUNCTION public.care_clinical_author(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.care_appointments a JOIN public.livestock l ON l.id=a.livestock_id WHERE a.id=_id AND a.vet_id=auth.uid() AND a.status IN('confirmed','completed') AND l.status='active' AND public.care_has_share(a.farmer_id,a.vet_id,a.livestock_id)); $$; REVOKE ALL ON FUNCTION public.care_clinical_author(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_clinical_author(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_save_consultation(_appointment uuid,_report text,_assessment text,_recommendations text,_follow_up date DEFAULT NULL,_supersedes uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.care_appointments; cid uuid; BEGIN IF NOT public.care_clinical_author(_appointment) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; SELECT * INTO a FROM public.care_appointments WHERE id=_appointment; IF (_follow_up IS NOT NULL AND _follow_up<public.farm_today()) OR (_supersedes IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.care_consultations WHERE id=_supersedes AND appointment_id=_appointment AND author_id=auth.uid())) THEN RAISE EXCEPTION 'invalid_consultation'; END IF; INSERT INTO public.care_consultations(appointment_id,author_id,farmer_report,assessment,recommendations,follow_up_date,supersedes_id) VALUES(_appointment,auth.uid(),_report,btrim(_assessment),_recommendations,_follow_up,_supersedes) RETURNING id INTO cid; INSERT INTO public.care_audit(actor_id,farmer_id,vet_id,livestock_id,action,record_id) VALUES(auth.uid(),a.farmer_id,a.vet_id,a.livestock_id,'consultation_saved',cid); INSERT INTO public.care_notifications(recipient_id,appointment_id,kind,dedupe_key) VALUES(a.farmer_id,a.id,'consultation',cid::text); RETURN cid; END $$; REVOKE ALL ON FUNCTION public.care_save_consultation(uuid,text,text,text,date,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_save_consultation(uuid,text,text,text,date,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_issue_prescription(_appointment uuid,_consultation uuid,_medicine text,_dose text,_route text,_frequency text,_duration text,_instructions text,_withdrawal text,_confirmed boolean,_supersedes uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.vet_public_profiles; a public.care_appointments; pid uuid; BEGIN IF NOT _confirmed OR NOT public.care_clinical_author(_appointment) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF NOT EXISTS(SELECT 1 FROM public.care_consultations WHERE id=_consultation AND appointment_id=_appointment AND author_id=auth.uid()) OR (_supersedes IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.care_prescriptions WHERE id=_supersedes AND appointment_id=_appointment AND author_id=auth.uid())) THEN RAISE EXCEPTION 'invalid_prescription'; END IF; SELECT * INTO p FROM public.vet_public_profiles WHERE user_id=auth.uid(); IF p.user_id IS NULL OR btrim(p.licence)='' OR btrim(p.qualifications)='' THEN RAISE EXCEPTION 'credentials_required'; END IF; SELECT * INTO a FROM public.care_appointments WHERE id=_appointment; INSERT INTO public.care_prescriptions(appointment_id,consultation_id,author_id,vet_name,qualifications,licence,medicine,dose,route,frequency,duration,instructions,withdrawal_guidance,supersedes_id) VALUES(_appointment,_consultation,auth.uid(),p.display_name,p.qualifications,p.licence,btrim(_medicine),btrim(_dose),btrim(_route),btrim(_frequency),btrim(_duration),_instructions,_withdrawal,_supersedes) RETURNING id INTO pid; INSERT INTO public.care_audit(actor_id,farmer_id,vet_id,livestock_id,action,record_id) VALUES(auth.uid(),a.farmer_id,a.vet_id,a.livestock_id,'prescription_issued',pid); INSERT INTO public.care_notifications(recipient_id,appointment_id,kind,dedupe_key) VALUES(a.farmer_id,a.id,'prescription',pid::text); RETURN pid; END $$; REVOKE ALL ON FUNCTION public.care_issue_prescription(uuid,uuid,text,text,text,text,text,text,text,boolean,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_issue_prescription(uuid,uuid,text,text,text,text,text,text,text,boolean,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_record_administration(_prescription uuid,_date date,_by text,_notes text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.care_appointments; rid uuid; BEGIN SELECT a0.* INTO a FROM public.care_appointments a0 JOIN public.care_prescriptions p ON p.appointment_id=a0.id WHERE p.id=_prescription; IF a.id IS NULL OR a.farmer_id<>auth.uid() OR NOT public.has_role(auth.uid(),'farmer') OR _date>public.farm_today() OR _date<date '1950-01-01' OR NOT EXISTS(SELECT 1 FROM public.livestock WHERE id=a.livestock_id AND owner_id=auth.uid() AND status='active') OR EXISTS(SELECT 1 FROM public.care_prescriptions WHERE supersedes_id=_prescription) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; INSERT INTO public.care_administrations(prescription_id,farmer_id,administration_date,administered_by,notes) VALUES(_prescription,auth.uid(),_date,btrim(_by),_notes) RETURNING id INTO rid; RETURN rid; END $$; REVOKE ALL ON FUNCTION public.care_record_administration(uuid,date,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_record_administration(uuid,date,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'immutable_record' USING ERRCODE='42501'; END $$;
CREATE TRIGGER care_consultation_immutable BEFORE UPDATE OR DELETE ON public.care_consultations FOR EACH ROW EXECUTE FUNCTION public.care_immutable(); CREATE TRIGGER care_prescription_immutable BEFORE UPDATE OR DELETE ON public.care_prescriptions FOR EACH ROW EXECUTE FUNCTION public.care_immutable(); CREATE TRIGGER care_audit_immutable BEFORE UPDATE OR DELETE ON public.care_audit FOR EACH ROW EXECUTE FUNCTION public.care_immutable(); CREATE TRIGGER care_administration_immutable BEFORE UPDATE OR DELETE ON public.care_administrations FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE OR REPLACE FUNCTION public.care_followup_notifications() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'farmer') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; INSERT INTO public.care_notifications(recipient_id,appointment_id,kind,dedupe_key) SELECT a.farmer_id,a.id,'follow_up',c.id::text||':followup' FROM public.care_consultations c JOIN public.care_appointments a ON a.id=c.appointment_id JOIN public.livestock l ON l.id=a.livestock_id WHERE a.farmer_id=auth.uid() AND l.status='active' AND c.follow_up_date<=public.farm_today()+7 AND NOT EXISTS(SELECT 1 FROM public.care_consultations n WHERE n.supersedes_id=c.id) ON CONFLICT DO NOTHING; END $$; REVOKE ALL ON FUNCTION public.care_followup_notifications() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_followup_notifications() TO authenticated;